<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Markup Calculator Online','description'=>'Calculate selling price, markup amount and profit from cost.','url'=>'https://smarttoolz.in/tools/markup-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Markup Calculator</h1><p>Calculate selling price from cost and markup.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Cost<input id="c" type="number" value="1000"></label><label>Markup %<input id="m" type="number" value="20"></label><button id="go" class="tool-btn">Calculate</button><p id="o"></p></div></section></main><script>go.onclick=()=>{let C=+c.value,M=+m.value,x=C*M/100;o.textContent=`Markup: ${x.toFixed(2)} · Selling price: ${(C+x).toFixed(2)}`}</script><?php smarttoolz_tool_page_end(); ?>